{"path": "task.py", "content": "import math

def rational_reduce(num, den):
    if den == 0:
        raise ValueError("Denominator cannot be zero")
    gcd = math.gcd(num, den)
    num //= gcd
    den //= gcd
    if den < 0:
        num = -num
        den = -den
    return num, den"}

